/* ============ TOAST + SOUND ============ */
var _toastQueue=[];var _toastActive=false;
function triggerConfetti(){var colors=['#ff0055','#7a00ff','#00c6ff','#ffd700','#28a745','#ec4899','#f59e0b','#10b981'];var c=document.getElementById('confettiContainer');if(!c)return;c.innerHTML='';for(var i=0;i<40;i++){(function(){var p=document.createElement('div');var col=colors[Math.floor(Math.random()*colors.length)];var sz=6+Math.random()*8;var sx=Math.random()*100;var dur=1800+Math.random()*1500;var r0=Math.random()*360,r1=r0+360+Math.random()*720;p.style.cssText='position:absolute;left:'+sx+'%;top:-10%;width:'+sz+'px;height:'+sz+'px;background:'+col+';border-radius:'+(Math.random()<0.5?'50%':'2px')+';';c.appendChild(p);p.animate([{transform:'translateY(0) rotate('+r0+'deg)',opacity:1},{transform:'translateY('+(window.innerHeight+120)+'px) rotate('+r1+'deg)',opacity:0}],{duration:dur,easing:'cubic-bezier(.2,.6,.4,1)',fill:'forwards'});setTimeout(function(){if(p.parentNode)p.parentNode.removeChild(p);},dur+200);})();}}
/* SOUND via Web Audio API (no files needed) */
var _audioCtx=null;var _soundEnabled=true;
function initAudio(){if(_audioCtx)return;try{_audioCtx=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}
function playBeep(freq,dur,type){if(!_soundEnabled||!currentUser||currentUser.soundEnabled===false)return;initAudio();if(!_audioCtx)return;try{var o=_audioCtx.createOscillator();var g=_audioCtx.createGain();o.type=type||'sine';o.frequency.value=freq;g.gain.setValueAtTime(0.08,_audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(0.001,_audioCtx.currentTime+dur);o.connect(g);g.connect(_audioCtx.destination);o.start();o.stop(_audioCtx.currentTime+dur);}catch(e){}}
function sfxClick(){playBeep(600,0.06,'square');}
function sfxCoin(){playBeep(880,0.08);setTimeout(function(){playBeep(1320,0.1);},70);}
function sfxSpin(){playBeep(400,0.05);}
function sfxNotif(){playBeep(1000,0.15,'sine');}
function toggleSound(){if(!currentUser){showToast('Login required','error');return;}currentUser.soundEnabled=!(currentUser.soundEnabled!==false);saveUserData();var b=document.getElementById('soundToggleBtn');if(b)b.innerText=currentUser.soundEnabled?'🔊':'🔇';showToast(currentUser.soundEnabled?'🔊 Sound ON':'🔇 Sound OFF','info');}
function _sfxUpdateBtn(){var b=document.getElementById('soundToggleBtn');if(b&&currentUser)b.innerText=currentUser.soundEnabled===false?'🔇':'🔊';}
document.addEventListener('click',function(e){if(e.target&&e.target.tagName==='BUTTON')sfxClick();},true);

/* ============ DARK MODE ============ */
function toggleDarkMode(){if(!currentUser){var on=!document.body.classList.contains('dark');document.body.classList.toggle('dark',on);return;}currentUser.darkMode=!currentUser.darkMode;saveUserData();document.body.classList.toggle('dark',currentUser.darkMode);var b=document.getElementById('dmToggleBtn');if(b)b.innerText=currentUser.darkMode?'☀️':'🌙';}

/* ============ AGE UI ============ */
function openAgeUi(mode){currentAgeUiMode=mode||'verify';renderAgeUi();var o=document.getElementById('ageUiOverlay');if(o)o.classList.add('active');document.body.style.overflow='hidden';}
function closeAgeUi(){var o=document.getElementById('ageUiOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';}
function openAgeAppeal(){currentAgeUiMode='appeal';renderAgeUi();var o=document.getElementById('ageAppealOverlay');if(o)o.classList.add('active');document.body.style.overflow='hidden';}
function closeAgeAppeal(){var o=document.getElementById('ageAppealOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';}
function closeAgeRequest(){var o=document.getElementById('ageRequestOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';currentAgeRequestId=null;}
function renderAgeUi(){
  var c=document.getElementById('ageUiContent');if(!c||!currentUser)return;
  if(currentAgeUiMode==='verify'){
    var u=currentUser;var already=isAgeVerified(u);var statusHtml='';
    if(already)statusHtml='<div class="age-form-box" style="border-color:#10b981"><h3 style="color:#10b981">✅ Age Already Verified</h3><p>Verified: <b>'+escapeHtml(String(u.verifiedAgeValue))+' years old</b></p></div>';
    c.innerHTML='<div class="age-form-box"><h3>📖 How It Works</h3><ol style="padding-left:20px;line-height:1.9;font-size:.9rem"><li>Fill form + upload clear ID photo.</li><li>App estimates your age from photo.</li><li>Owner reviews your request.</li><li>Users 13 and below cannot cash out.</li></ol></div>'+statusHtml+(!already?'<div class="age-form-box"><h3>🪪 Submit Age Verification</h3><label>Photo / Document</label><input type="file" id="agePhotoInput" accept="image/*"><img id="agePhotoPreview" class="age-preview-img" style="display:none"><label>Your Age</label><input type="number" id="ageInput" min="1" max="120"><label>Name</label><input type="text" id="ageNameInput" value="'+escapeHtml(currentUser.name||'')+'"><label>Gmail</label><input type="text" id="ageGmailInput" value="'+escapeHtml(currentUser.gmail||'')+'"><label>Number</label><input type="text" id="ageNumberInput" value="'+escapeHtml(currentUser.number||'')+'"><button class="age-submit-btn" onclick="submitAgeVerification()">📤 Submit</button></div>':'');
    var p=document.getElementById('agePhotoInput');if(p)p.onchange=function(e){var f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024){showToast("❌ Max 3MB","error");e.target.value='';return;}var r=new FileReader();r.onload=function(ev){var pr=document.getElementById('agePhotoPreview');pr.src=ev.target.result;pr.style.display='block';pr.dataset.data=ev.target.result;};r.readAsDataURL(f);};
  }else if(currentAgeUiMode==='appeal'){
    var u2=currentUser;var isP=isOwnerOrCoOwner(u2);var att=u2.ageAppealCount||0;var lastT=u2.lastAgeAppealTime||0;var now=Date.now();var cd=30*60*1000;var canSub=isP?true:(att<5&&(now-lastT>=cd));
    var sH='';if(isP)sH='<div class="age-form-box" style="border-color:#fbbf24"><h3 style="color:#fbbf24">👑 Owner Mode — No Cooldown</h3></div>';else if(att>=5)sH='<div class="age-form-box" style="border-color:#dc3545"><h3 style="color:#dc3545">❌ Limit (5/5)</h3></div>';else if(!canSub)sH='<div class="age-form-box" style="border-color:#f59e0b"><h3 style="color:#f59e0b">⏳ Cooldown</h3><p>Attempts: '+att+'/5</p></div>';else sH='<div class="age-form-box" style="border-color:#10b981"><h3 style="color:#10b981">✅ Ready ('+att+'/5)</h3></div>';
    c.innerHTML='<div class="age-form-box"><h3>📩 Age Appeal</h3><p>If you believe your age is wrong, submit an appeal.</p></div>'+sH+'<div class="age-form-box"><h3>👤 Auto-Filled</h3><div style="background:rgba(0,0,0,.3);border-radius:8px;padding:14px;font-size:.9rem;line-height:2"><div>👤 <b>Name:</b> '+escapeHtml(u2.name||'N/A')+'</div><div>🎂 <b>Current Age:</b> '+escapeHtml(u2.verifiedAgeValue||'Not verified')+'</div></div><label>📎 Upload Photo</label><input type="file" id="appealPhotoInput" accept="image/*"><img id="appealPhotoPreview" class="age-preview-img" style="display:none"><label>🎂 Your Age</label><input type="number" id="appealAgeInput"><div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap"><button class="age-submit-btn" style="flex:1;margin-top:0" onclick="submitAgeAppeal()" '+(canSub?'':'disabled')+'>📩 Submit</button><button class="age-submit-btn" style="flex:1;margin-top:0;background:linear-gradient(135deg,#f59e0b,#ef4444)" onclick="requestAgainAgeAppeal()" '+(canSub?'':'disabled')+'>🔄 Request Again</button></div></div>';
    var p2=document.getElementById('appealPhotoInput');if(p2)p2.onchange=function(e){var f=e.target.files[0];if(!f)return;if(f.size>3*1024*1024){showToast("❌ Max 3MB","error");e.target.value='';return;}var r=new FileReader();r.onload=function(ev){var pr=document.getElementById('appealPhotoPreview');pr.src=ev.target.result;pr.style.display='block';pr.dataset.data=ev.target.result;};r.readAsDataURL(f);};
  }
}
function estimateAgeFromPhoto(d,u){if(!u)u=13;var n=u+(Math.random()<0.3?1:(Math.random()<0.5?-1:0));return Math.max(1,Math.min(120,n));}
async function submitAgeVerification(){if(!currentUser)return;var ph=(document.getElementById('agePhotoPreview')||{}).dataset;var photo=ph?ph.data:'';var ua=parseInt(document.getElementById('ageInput').value,10);var nm=(document.getElementById('ageNameInput').value||'').trim();var em=(document.getElementById('ageGmailInput').value||'').trim();var nu=(document.getElementById('ageNumberInput').value||'').trim();if(!photo){showToast("❌ Upload photo","error");return;}if(isNaN(ua)||ua<1){showToast("❌ Enter age","error");return;}if(!nm){showToast("❌ Enter name","error");return;}var est=estimateAgeFromPhoto(photo,ua);var rid="AGEREQ-"+Date.now();var rq={id:rid,userId:String(currentUser.rblxUserId),userName:nm,userGmail:em,userNumber:nu,userInputAge:ua,estimatedAge:est,photo:photo,status:'pending',timestamp:Date.now(),type:'new'};try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(rq)});var nid="NOTIF-AGEREQ-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🪪 New Age Request",message:nm+' Est: '+est,timestamp:Date.now(),isAgeRequest:true,requestId:rid})});showToast("✅ Submitted!","success");closeAgeUi();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function submitAgeAppeal(){if(!currentUser)return;var ph=(document.getElementById('appealPhotoPreview')||{}).dataset;var photo=ph?ph.data:'';var age=parseInt(document.getElementById('appealAgeInput').value,10);if(!photo||isNaN(age)||age<1){showToast("❌ Fill all","error");return;}var isP=isOwnerOrCoOwner(currentUser);var att=currentUser.ageAppealCount||0;if(!isP&&(att>=5||Date.now()-(currentUser.lastAgeAppealTime||0)<30*60*1000)){showToast("❌ Limit","error");return;}var est=estimateAgeFromPhoto(photo,age);var rid="AGEAPPEAL-"+Date.now();var rq={id:rid,userId:String(currentUser.rblxUserId),userName:currentUser.name,userInputAge:age,estimatedAge:est,currentVerifiedAge:currentUser.verifiedAgeValue||null,photo:photo,status:'pending',timestamp:Date.now(),type:'appeal',isOwnerAppeal:isP};currentUser.ageAppealCount=(currentUser.ageAppealCount||0)+1;currentUser.lastAgeAppealTime=Date.now();currentUser.pendingAgeAppeal=rid;saveUserData();try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(rq)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"📩 Age Appeal",message:currentUser.name+' Est: '+est,timestamp:Date.now(),isAgeAppeal:true,requestId:rid})});showToast("✅ Submitted!","success");closeAgeAppeal();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function requestAgainAgeAppeal(){if(!currentUser)return;var isP=isOwnerOrCoOwner(currentUser);var att=currentUser.ageAppealCount||0;if(!isP&&(att>=5||Date.now()-(currentUser.lastAgeAppealTime||0)<30*60*1000)){showToast("❌ Limit","error");return;}var ph=(document.getElementById('appealPhotoPreview')||{}).dataset;var photo=ph?ph.data:'';var age=parseInt(document.getElementById('appealAgeInput').value,10);if(!photo||isNaN(age)||age<1){showToast("❌ Fill all","error");return;}var est=estimateAgeFromPhoto(photo,age);var rid="AGEAPPEAL-AGAIN-"+Date.now();var rq={id:rid,userId:String(currentUser.rblxUserId),userName:currentUser.name,userInputAge:age,estimatedAge:est,photo:photo,status:'pending',timestamp:Date.now(),type:'appeal',isRequestAgain:true,isOwnerAppeal:isP};currentUser.ageAppealCount=(currentUser.ageAppealCount||0)+1;currentUser.lastAgeAppealTime=Date.now();saveUserData();try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(rq)});showToast("🔄 Sent!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function openAgeRequest(rid){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}currentAgeRequestId=rid;var c=document.getElementById('ageRequestContent');c.innerHTML='<p>Loading...</p>';var o=document.getElementById('ageRequestOverlay');if(o)o.classList.add('active');try{var r=await fetch(FIREBASE_BASE_URL+'/age_requests/'+rid+'.json');var d=await r.json();if(!d){c.innerHTML='<p>Not found.</p>';return;}renderAgeRequest(d);}catch(e){c.innerHTML='<p>Failed.</p>';}}
function renderAgeRequest(data){var c=document.getElementById('ageRequestContent');var isA=data.type==='appeal';var safePhoto=(typeof data.photo==='string'&&/^data:image\//.test(data.photo))?data.photo:'';c.innerHTML='<div class="age-request-card"><h3>'+(isA?'📩 Age Appeal':'🪪 Age Verification')+'</h3><div class="ar-info"><div><b>ID:</b> '+escapeHtml(data.id)+'</div><div><b>Submitted:</b> '+new Date(data.timestamp).toLocaleString()+'</div><div><b>Status:</b> '+escapeHtml(data.status)+'</div></div></div><div class="age-request-card"><h3>👤 User</h3><div class="ar-info"><div><b>Name:</b> '+escapeHtml(data.userName||'N/A')+'</div><div><b>Input Age:</b> '+escapeHtml(String(data.userInputAge||'N/A'))+'</div><div><b>Estimated:</b> '+escapeHtml(String(data.estimatedAge||'N/A'))+'</div><div><b>User ID:</b> '+escapeHtml(data.userId)+'</div></div></div><div class="age-request-card"><h3>📎 Document</h3>'+(safePhoto?'<img class="ar-photo" src="'+safePhoto+'">':'<p>No photo.</p>')+'</div><div class="age-request-card"><h3>✏️ Set New Age</h3><input type="number" id="ownerNewAge" min="1" max="120" value="'+(parseInt(data.estimatedAge,10)||13)+'" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:4px;margin-bottom:12px"><div style="display:flex;gap:10px"><button class="btn-claim" style="flex:1;background:#10b981" onclick="approveAgeRequest()">✅ Approve</button><button class="btn-danger" style="flex:1" onclick="rejectAgeRequest()">❌ Reject</button></div></div>';}
async function approveAgeRequest(){if(!currentUser||!isOwnerOrCoOwner(currentUser)||!currentAgeRequestId)return;var na=parseInt(document.getElementById('ownerNewAge').value,10);if(isNaN(na)||na<1){showToast("❌ Invalid","error");return;}try{var r=await fetch(FIREBASE_BASE_URL+'/age_requests/'+currentAgeRequestId+'.json');var d=await r.json();var uid=d.userId;var all=safeGetJSON('app_users_db',[]);var idx=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(uid)){idx=i;break;}}if(idx!==-1){all[idx].verifiedAge=true;all[idx].verifiedAgeValue=na;all[idx].ageVerificationDate=Date.now();all[idx].ageVerifiedBy=currentUser.username||currentUser.name;all[idx].pendingAgeAppeal=null;localStorage.setItem('app_users_db',JSON.stringify(all));await fetch(FIREBASE_BASE_URL+'/users/'+uid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[idx])});if(String(uid)===String(currentUser.rblxUserId)){currentUser.verifiedAge=true;currentUser.verifiedAgeValue=na;saveUserData();updateUserStatusHeader();}}await fetch(FIREBASE_BASE_URL+'/age_requests/'+currentAgeRequestId+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify('approved')});showToast("✅ Approved!","success");closeAgeRequest();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function rejectAgeRequest(){if(!currentUser||!isOwnerOrCoOwner(currentUser)||!currentAgeRequestId)return;if(!confirm("Reject?"))return;try{await fetch(FIREBASE_BASE_URL+'/age_requests/'+currentAgeRequestId+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify('rejected')});showToast("✅ Rejected","success");closeAgeRequest();syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}

/* ============ IMG SHOT ============ */
function generateImgShotCode(){var ch='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';var c='xdrgimg';for(var i=0;i<6;i++)c+=ch[Math.floor(Math.random()*ch.length)];return c;}
function openVideoShares(){vsTab='fyt';document.querySelectorAll('.tt-tab').forEach(function(b){b.classList.toggle('active',b.dataset.tab==='fyt');});openSwapUI('videoSharesOverlay');renderImgShotFeed();}
function setVsTab(tab){vsTab=tab;document.querySelectorAll('.tt-tab').forEach(function(b){b.classList.toggle('active',b.dataset.tab===tab);});renderImgShotFeed();}
function getFilteredImgShots(){var all=getAllImgShots();if(!currentUser)return all;if(vsTab==='friends'){var fids=(currentUser.friends||[]).map(String);return all.filter(function(v){return fids.indexOf(String(v.uploaderId))!==-1;});}if(vsTab==='following'){var fls=(currentUser.following||[]).map(String);return all.filter(function(v){return fls.indexOf(String(v.uploaderId))!==-1;});}return all.slice().sort(function(a,b){return (b.timestamp||0)-(a.timestamp||0);});}
function isFollowingUser(uid){if(!currentUser)return false;return (currentUser.following||[]).map(String).indexOf(String(uid))!==-1;}
function renderImgShotFeed(){var feed=document.getElementById('ttFeed');if(!feed)return;if(ttObserver){ttObserver.disconnect();ttObserver=null;}var meId=currentUser?String(currentUser.rblxUserId):'guest';var list=getFilteredImgShots().reverse();if(list.length===0){feed.innerHTML='<div class="tt-item"><div class="tt-empty">📭 No images yet.</div></div>';return;}var allUsers=safeGetJSON('app_users_db',[]);feed.innerHTML=list.map(function(v){var liked=(v.likes||[]).map(String).indexOf(meId)!==-1;var saved=(v.savedBy||[]).map(String).indexOf(meId)!==-1;var following=isFollowingUser(v.uploaderId);var isMe=String(v.uploaderId)===meId;var av=getRobloxAvatarUrl(v.uploaderId);var up=null;for(var i=0;i<allUsers.length;i++){if(String(allUsers[i].rblxUserId)===String(v.uploaderId)){up=allUsers[i];break;}}var vb=verifiedBadgeHtml(up);var ab=up?getAgeBadge(up):'';var mh=v.media?'<img class="tt-media" src="'+escapeHtml(v.media)+'">':'<div class="tt-media" style="display:flex;align-items:center;justify-content:center;font-size:6rem">🖼️</div>';return '<div class="tt-item">'+mh+'<div class="tt-overlay-left"><div class="tt-uploader-row"><img class="tt-avatar" src="'+av+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div class="tt-uploader-name">@'+escapeHtml(v.uploaderUsername||'user')+vb+ab+'</div></div></div><div class="tt-title">'+escapeHtml(v.title||'Untitled')+'</div>'+(v.description?'<div class="tt-desc">'+escapeHtml(v.description)+'</div>':'')+'<div class="tt-code-tag">'+escapeHtml(v.code||'')+'</div></div><div class="tt-overlay-right"><button class="tt-action"><img class="tt-action-avatar" src="'+av+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"></button>'+(isMe?'':'<button class="tt-action" onclick="followUserToggle(\''+v.uploaderId+'\')"><span class="tt-action-icon">'+(following?'✓':'➕')+'</span><span>'+(following?'Following':'Follow')+'</span></button>')+'<button class="tt-action" onclick="toggleImgShotLike(\''+v.id+'\')"><span class="tt-action-icon">'+(liked?'❤️':'🤍')+'</span><span>'+(v.likes||[]).length+'</span></button><button class="tt-action" onclick="toggleImgShotSave(\''+v.id+'\')"><span class="tt-action-icon">'+(saved?'⭐':'🔖')+'</span><span>'+(saved?'Saved':'Save')+'</span></button><button class="tt-action" onclick="shareImgShot(\''+v.id+'\')"><span class="tt-action-icon">↗️</span><span>'+(v.views||0)+'👁</span></button></div></div>';}).join('');}
function goHomeFromVideo(){closeSwapUI('videoSharesOverlay');openProfileViewers();}
function openClaimedRewards(){renderClaimedRewards();openSwapUI('claimedRewardsOverlay');}
function renderClaimedRewards(){var c=document.getElementById('claimedRewardsContent');if(!c)return;if(!currentUser){c.innerHTML='<p style="text-align:center">Login required.</p>';return;}var meId=String(currentUser.rblxUserId);var my=getAllImgShots().filter(function(v){return String(v.uploaderId)===meId;});var tv=my.reduce(function(s,v){return s+(v.views||0);},0);var tl=my.reduce(function(s,v){return s+(v.likes||[]).length;},0);var tf=(currentUser.followers||[]).length;var te=(tf*10)+(tl*5)+Math.floor(tv/10);c.innerHTML='<div style="max-width:900px;margin:0 auto;padding:20px"><div style="background:linear-gradient(135deg,#059669,#10b981);padding:24px;border-radius:14px;text-align:center"><h2 style="margin:0;border:none;color:#fff">💸 Monetization</h2><div style="font-size:2.4rem;font-weight:900;color:#fff;margin:8px 0">🪙 '+te.toLocaleString()+'</div></div></div>';}
function openUploadUI(){if(!currentUser){showToast("❌ Login first","error");return;}uploadFileData=null;var fi=document.getElementById('ttFileInput');if(fi)fi.value='';var ti=document.getElementById('ttUploadTitle');if(ti)ti.value='';var de=document.getElementById('ttUploadDesc');if(de)de.value='';var pv=document.getElementById('ttUploadPreview');if(pv){pv.style.display='none';pv.innerHTML='';}var m=document.getElementById('uploadModal');if(m)m.classList.add('active');}
function closeUploadUI(){var m=document.getElementById('uploadModal');if(m)m.classList.remove('active');}
function handleUploadFile(input){var f=input.files&&input.files[0];if(!f)return;if(f.size>6*1024*1024){showToast("❌ Max 6MB","error");input.value='';return;}if((f.type||'').indexOf('image/')!==0){showToast("❌ Images only","error");input.value='';return;}var r=new FileReader();r.onload=function(e){uploadFileData={dataUrl:e.target.result};var pv=document.getElementById('ttUploadPreview');if(pv){pv.style.display='flex';pv.innerHTML='<img src="'+e.target.result+'">';}};r.readAsDataURL(f);}
async function submitUpload(){if(!currentUser)return;var t=(document.getElementById('ttUploadTitle').value||'').trim();var d=(document.getElementById('ttUploadDesc').value||'').trim();if(!t){showToast("❌ Title required","error");return;}if(!uploadFileData){showToast("❌ Pick image","error");return;}var code=generateImgShotCode();var vid="IMG-"+Date.now();var obj={id:vid,code:code,title:t,description:d,media:uploadFileData.dataUrl,mediaType:'image',uploaderId:String(currentUser.rblxUserId),uploaderName:currentUser.displayName||currentUser.name,uploaderUsername:currentUser.username,views:0,likes:[],savedBy:[],timestamp:Date.now()};var all=getAllImgShots();all.push(obj);saveAllImgShots(all);try{await fetch(FIREBASE_BASE_URL+'/img_shots/'+vid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(obj)});}catch(e){}closeUploadUI();showToast("✅ Uploaded! "+code,"success");renderImgShotFeed();}
function toggleImgShotLike(id){if(!currentUser){showToast("❌ Login","error");return;}var me=String(currentUser.rblxUserId);var all=getAllImgShots();var v=null;for(var i=0;i<all.length;i++){if(all[i].id===id){v=all[i];break;}}if(!v)return;if(!v.likes)v.likes=[];var ix=v.likes.map(String).indexOf(me);if(ix===-1)v.likes.push(me);else v.likes.splice(ix,1);saveAllImgShots(all);fetch(FIREBASE_BASE_URL+'/img_shots/'+id+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(v)}).catch(function(){});renderImgShotFeed();}
function toggleImgShotSave(id){if(!currentUser){showToast("❌ Login","error");return;}var me=String(currentUser.rblxUserId);var all=getAllImgShots();var v=null;for(var i=0;i<all.length;i++){if(all[i].id===id){v=all[i];break;}}if(!v)return;if(!v.savedBy)v.savedBy=[];var ix=v.savedBy.map(String).indexOf(me);if(ix===-1)v.savedBy.push(me);else v.savedBy.splice(ix,1);saveAllImgShots(all);fetch(FIREBASE_BASE_URL+'/img_shots/'+id+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(v)}).catch(function(){});renderImgShotFeed();}
function shareImgShot(id){var all=getAllImgShots();var v=null;for(var i=0;i<all.length;i++){if(all[i].id===id){v=all[i];break;}}if(!v)return;var url=window.location.protocol+'//'+window.location.host+window.location.pathname+'?xdrgimg='+v.code;if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(url).then(function(){showToast("🔗 Copied!","success");},function(){prompt("Copy:",url);});}else prompt("Copy:",url);}
async function followUserToggle(tid){if(!currentUser){showToast("❌ Login","error");return;}var me=String(currentUser.rblxUserId);var t=String(tid);if(me===t)return;if(!currentUser.following)currentUser.following=[];var ix=currentUser.following.map(String).indexOf(t);var nowF=ix===-1;if(nowF)currentUser.following.push(t);else currentUser.following.splice(ix,1);saveUserData();var all=safeGetJSON('app_users_db',[]);var ti=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===t){ti=i;break;}}if(ti!==-1){if(!all[ti].followers)all[ti].followers=[];var fi=all[ti].followers.map(String).indexOf(me);if(nowF&&fi===-1)all[ti].followers.push(me);else if(!nowF&&fi!==-1)all[ti].followers.splice(fi,1);localStorage.setItem('app_users_db',JSON.stringify(all));fetch(FIREBASE_BASE_URL+'/users/'+t+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[ti])}).catch(function(){});}renderImgShotFeed();}
function activateVerifiedBadge(){if(!currentUser)return;currentUser.isVerified=true;saveUserData();updateUserStatusHeader();showToast("✅ Verified Badge activated!","success");renderNotificationDropdown();}

/* ============ LUCKY SPIN ============ */
function openLuckySpin(){renderLuckySpinOverlay();openSwapUI('luckySpinOverlay');}
function getSpinCooldownRemaining(){var last=safeGetJSON('spin_last_'+((currentUser&&currentUser.rblxUserId)||'guest'),0);return Math.max(0,30*60*1000-(Date.now()-last));}
function formatSpinTime(ms){var s=Math.floor(ms/1000);var m=Math.floor(s/60);var sec=s%60;return String(m).padStart(2,'0')+':'+String(sec).padStart(2,'0');}
function renderLuckySpinOverlay(){var c=document.getElementById('luckySpinContent');var rem=getSpinCooldownRemaining();var hasExtra=currentUser&&(currentUser.extraSpins||0)>0;var ready=rem<=0||hasExtra;var n=SPIN_SEGMENTS.length;var sa=360/n;var conic=[];SPIN_SEGMENTS.forEach(function(s,i){conic.push(s.color+' '+(i*sa)+'deg '+((i+1)*sa)+'deg');});var lh='';SPIN_SEGMENTS.forEach(function(s,i){var a=i*sa+sa/2;lh+='<div class="spin-label" style="transform:translate(-50%,-50%) rotate('+a+'deg) translateY(-115px);"><span style="display:inline-block;transform:rotate('+(-a)+'deg);">'+s.label+'</span></div>';});var lg=SPIN_SEGMENTS.map(function(s){return '<div><span>'+s.label+'</span><small style="opacity:.7">'+s.weight+'%</small></div>';}).join('');var bl;if(ready&&hasExtra&&rem>0)bl='🎯 SPIN NOW ('+currentUser.extraSpins+' Extra)';else if(ready)bl='🎯 SPIN NOW';else bl='⏳ '+formatSpinTime(rem);c.innerHTML='<div style="text-align:center;padding:20px 0"><h2 style="color:#fbbf24;border:none;margin-bottom:8px">🎰 Lucky Spin</h2><p style="color:#94a3b8">Every 30 minutes!</p><div class="spin-wheel-box"><div class="spin-pointer">🔻</div><div class="spin-wheel" id="spinWheel" style="transform:rotate('+spinRotation+'deg);background:conic-gradient('+conic.join(',')+')">'+lh+'<div class="spin-center">SPIN</div></div></div><button class="spin-btn" id="spinBtn" '+(ready?'':'disabled')+' onclick="doLuckySpin()">'+bl+'</button><div class="spin-legend">'+lg+'</div></div>';if(!ready){if(window._spinCdInt)clearInterval(window._spinCdInt);window._spinCdInt=setInterval(function(){var b=document.getElementById('spinBtn');if(!b){clearInterval(window._spinCdInt);window._spinCdInt=null;return;}var r=getSpinCooldownRemaining();if(r<=0){b.disabled=false;b.textContent='🎯 SPIN NOW';clearInterval(window._spinCdInt);window._spinCdInt=null;}else b.textContent='⏳ '+formatSpinTime(r);},1000);}}
function doLuckySpin(){if(spinInProgress)return;var rem=getSpinCooldownRemaining();var hasExtra=currentUser&&(currentUser.extraSpins||0)>0;var useExtra=rem>0&&hasExtra;if(rem>0&&!hasExtra){showToast("⏳ Wait "+formatSpinTime(rem),"info");return;}spinInProgress=true;var b=document.getElementById('spinBtn');if(b)b.disabled=true;var tw=SPIN_SEGMENTS.reduce(function(a,s){return a+s.weight;},0);var r=Math.random()*tw;var wi=0,acc=0;for(var i=0;i<SPIN_SEGMENTS.length;i++){acc+=SPIN_SEGMENTS[i].weight;if(r<=acc){wi=i;break;}}var seg=SPIN_SEGMENTS[wi];var n=SPIN_SEGMENTS.length;var sa=360/n;var center=wi*sa+sa/2;var cm=((spinRotation%360)+360)%360;var tm=(360-center+360)%360;var delta=(tm-cm+360)%360;spinRotation+=360*5+delta;var w=document.getElementById('spinWheel');if(w)w.style.transform='rotate('+spinRotation+'deg)';setTimeout(async function(){spinInProgress=false;if(useExtra){currentUser.extraSpins=(currentUser.extraSpins||0)-1;saveUserData();}else localStorage.setItem('spin_last_'+((currentUser&&currentUser.rblxUserId)||'guest'),JSON.stringify(Date.now()));var msg='';if(seg.vip){if(currentUser){currentUser.isVIP=true;saveUserData();updateUserStatusHeader();}msg='⭐ VIP 24h!';}else if(seg.cash){if(currentUser){currentUser.cashBalance=(currentUser.cashBalance||0)+seg.cash;saveUserData();}msg='💰 PHP ₱'+seg.cash+'!';}else if(seg.nothing){msg='😭 Nothing!';}else if(seg.extraSpins){if(currentUser){currentUser.extraSpins=(currentUser.extraSpins||0)+seg.extraSpins;saveUserData();}msg='🎉 '+seg.extraSpins+' Extra Spins!';}else if(seg.verifiedTrial){if(currentUser){currentUser.isVerified=true;currentUser.verifiedExpiry=Date.now()+30*24*3600*1000;saveUserData();updateUserStatusHeader();}msg='🔵 Verified Badge (1mo)!';}else if(seg.coins){if(currentUser){currentUser.points=(currentUser.points||0)+seg.coins;saveUserData();updateUserStatusHeader();}msg='🪙 '+seg.coins.toLocaleString()+' Coins!';}if(currentUser){var nid="SPIN-"+Date.now();globalNotifications.unshift({id:nid,title:"🎰 Lucky Spin Result",message:'You won '+msg,timestamp:Date.now()});renderNotificationDropdown();}showToast('🎉 You won: '+msg,'success');if(!seg.nothing){triggerConfetti();sfxCoin();}renderLuckySpinOverlay();},4600);}

/* ============ NOTIFICATIONS ============ */
function checkDailyReward(){if(!currentUser)return;var t=new Date().toDateString();var l=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;if(l===t)return;var s=currentUser.streakCount||0;if(l){var y=new Date();y.setDate(y.getDate()-1);s=(l===y.toDateString())?s+1:1;}else s=1;if(s>7)s=1;currentUser.streakCount=s;saveUserData();globalNotifications.unshift({id:"DAILY-"+Date.now(),title:"🎁 Daily Reward Ready!",message:"Claim now!",timestamp:Date.now(),isDailyReward:true});renderNotificationDropdown();}
function claimDailyRewardAction(){if(!currentUser)return;var t=new Date().toDateString();var l=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;if(l===t){showToast("❌ Already claimed","error");return;}var s=currentUser.streakCount||1;var rc=s===7?100:50;if(currentUser.isPremium)rc*=3;else if(currentUser.isVIP)rc*=2;currentUser.points=(currentUser.points||0)+rc;currentUser.lastClaimedDate=new Date().toISOString();saveUserData();updateUserStatusHeader();globalNotifications=globalNotifications.filter(function(n){return !n.isDailyReward;});renderNotificationDropdown();showToast('🎉 Day '+s+'! +'+rc+' Coins!','success');triggerConfetti();sfxCoin();if(document.getElementById('pageTitle').innerText.indexOf('Quest')!==-1)renderQuestsPage();}
function toggleNotifDropdown(e){e.stopPropagation();var d=document.getElementById('notifDropdown');if(d)d.classList.toggle('active');}
function renderNotificationDropdown(){var le=document.getElementById('notifList');var be=document.getElementById('notifUnreadBadge');if(!le)return;var ri=safeGetJSON('read_notif_ids',[]);var uc=0;if(globalNotifications.length===0){le.innerHTML='<li class="notif-item" style="text-align:center;color:#777;padding:15px">No notifications yet.</li>';if(be)be.style.display="none";return;}var html="";globalNotifications.forEach(function(n){var isR=ri.indexOf(n.id)!==-1;if(!isR)uc++;var ds=n.timestamp?new Date(n.timestamp).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';var ah='';if(n.isCashOutCode)ah='<div class="notif-code-box">'+escapeHtml(n.codeDisplay||'')+'</div><button class="notif-automation-btn" onclick="automationFromNotification(\''+escapeHtml(n.codeDisplay||'')+'\')">⚡ Automation</button>';if(n.isAccountLockNotif)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#dc3545" onclick="showLockContinueModal()">Continue</button></div>';if(n.isFriendRequest)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#0d6efd" onclick="openFriendConfirmation()">View</button></div>';if(n.isNewMessage)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#17a2b8" onclick="openMessenger(\''+escapeHtml(n.fromUserId||'')+'\')">Open Chat</button></div>';if(n.isDailyReward&&currentUser){var td=new Date().toDateString();var ld=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;if(ld!==td)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#28a745" onclick="claimDailyRewardAction()">🎁 Claim!</button></div>';}if(n.isVerifiedBadge)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#1DA1F2" onclick="activateVerifiedBadge()">🔵 Get Badge</button></div>';if(n.isLimitedCashOut)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#f59e0b" onclick="openCashOutPage()">💸 Redeem!</button></div>';if(n.isCoinGift)ah='<div style="margin-top:6px;padding:8px;background:#e8f8f0;border-left:3px solid #28a745;border-radius:4px;font-size:.78rem;color:#155724;font-weight:bold">🪙 Coin Gift!</div>';if(n.isNewPoll)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#005a9c" onclick="openQuests()">📊 Vote</button></div>';if(n.isAgeRequest&&currentUser&&isOwnerOrCoOwner(currentUser))ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#8b5cf6" onclick="openAgeRequest(\''+escapeHtml(n.requestId||'')+'\')">📃 Review</button></div>';if(n.isAgeAppeal&&currentUser&&isOwnerOrCoOwner(currentUser))ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#8b5cf6" onclick="openAgeRequest(\''+escapeHtml(n.requestId||'')+'\')">📃 Review</button></div>';if(n.isShopOrder&&currentUser&&isOwnerOrCoOwner(currentUser))ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#8b5cf6" onclick="openStaffCommands()">🛒 View</button></div>';html+='<li class="notif-item '+(isR?'':'unread')+'"><div class="notif-title">'+escapeHtml(n.title||'Update')+'</div><div class="notif-msg">'+linkify(n.message||'')+'</div><div class="notif-time">'+ds+'</div>'+ah+'</li>';});le.innerHTML=html;if(be){if(uc>0){be.innerText=uc>99?'99+':uc;be.style.display="block";}else be.style.display="none";}}
function markAllNotificationsAsRead(){var ri=safeGetJSON('read_notif_ids',[]);var seen={};ri.forEach(function(x){seen[x]=1;});globalNotifications.forEach(function(n){seen[n.id]=1;});localStorage.setItem('read_notif_ids',JSON.stringify(Object.keys(seen)));renderNotificationDropdown();}

/* ============ SYNC ============ */
async function syncRealtimeDatabase(){try{var nn=[];var nr=await fetch(FIREBASE_BASE_URL+'/notifications.json');if(nr.ok){var nd=await nr.json();if(nd)Object.keys(nd).forEach(function(id){nn.push(Object.assign({id:id},nd[id]));});}if(currentUser){var ids=[String(currentUser.rblxUserId||'').toLowerCase(),(currentUser.gmail||'').toLowerCase(),(currentUser.username||'').toLowerCase()];for(var ii=0;ii<ids.length;ii++){var id=ids[ii];if(!id)continue;var ur=await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(id)+'.json');if(ur.ok){var ud=await ur.json();if(ud)Object.keys(ud).forEach(function(k){nn.push(Object.assign({id:k},ud[k]));});}}}if(currentUser&&isOwnerOrCoOwner(currentUser)){var oa=await fetch(FIREBASE_BASE_URL+'/owner_alerts.json');if(oa.ok){var od=await oa.json();if(od)Object.keys(od).forEach(function(id){nn.push(Object.assign({id:id},od[id]));});}}if(currentUser&&isStaff(currentUser)){var rr=await fetch(FIREBASE_BASE_URL+'/reports.json');if(rr.ok){var rd=await rr.json();if(rd){globalReports=[];Object.keys(rd).forEach(function(id){globalReports.push(Object.assign({id:id},rd[id]));});}}}try{var aU=await fetch(FIREBASE_BASE_URL+'/users.json');if(aU.ok){var aD=await aU.json();if(aD){var all=safeGetJSON('app_users_db',[]);Object.keys(aD).forEach(function(k){var u=aD[k];if(u&&u.rblxUserId){var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(u.rblxUserId)){ix=i;break;}}if(ix===-1)all.push(u);else all[ix]=Object.assign({},all[ix],u);}});if(all.length>500){all.sort(function(a,b){return (new Date(b.lastSeen||0).getTime())-(new Date(a.lastSeen||0).getTime());});all=all.slice(0,500);if(currentUser&&!all.some(function(u){return String(u.rblxUserId)===String(currentUser.rblxUserId);}))all.push(currentUser);}try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}if(currentUser){var me=null;for(var j=0;j<all.length;j++){if(String(all[j].rblxUserId)===String(currentUser.rblxUserId)){me=all[j];break;}}if(me){var sc=currentUser.shopCart;Object.keys(me).forEach(function(k){if(me[k]!==undefined&&k!=='shopCart'&&_CLIENT_OWNED_FIELDS.indexOf(k)===-1)currentUser[k]=me[k];});currentUser.shopCart=sc||currentUser.shopCart||[];try{localStorage.setItem('app_current_user',JSON.stringify(currentUser));}catch(e){}}}}}}catch(e){}try{var vs=await fetch(FIREBASE_BASE_URL+'/img_shots.json');if(vs.ok){var vd=await vs.json();if(vd){var rm=Object.keys(vd).map(function(k){return vd[k];}).filter(function(v){return v&&v.mediaType==='image';});var lc=getAllImgShots();var mp={};lc.forEach(function(v){mp[v.id]=v;});rm.forEach(function(v){if(!mp[v.id])mp[v.id]=v;else mp[v.id]=Object.assign({},mp[v.id],v);});saveAllImgShots(Object.keys(mp).map(function(k){return mp[k];}));}}}catch(e){}try{var lc2=await fetch(FIREBASE_BASE_URL+'/limited_cashout.json');if(lc2.ok){var ld=await lc2.json();if(ld&&ld.expiresAt&&ld.expiresAt>Date.now())globalLimitedCashOut=ld;else globalLimitedCashOut=null;}}catch(e){}try{var pr=await fetch(FIREBASE_BASE_URL+'/xdrg_shop/products.json');if(pr.ok){var pd=await pr.json();if(pd){var np=[];Object.keys(pd).forEach(function(id){np.push(Object.assign({id:id},pd[id]));});saveAllShopProducts(np);}}}catch(e){}try{var or=await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders.json');if(or.ok){var od2=await or.json();if(od2){var no=[];Object.keys(od2).forEach(function(id){no.push(Object.assign({id:id},od2[id]));});saveAllShopOrders(no);}}}catch(e){}try{var gs=await fetch(FIREBASE_BASE_URL+'/xdrg_game_setup.json');if(gs.ok){var gd=await gs.json();if(gd){if(gd.crystal_items)saveCustomCrystalItems(gd.crystal_items);if(gd.brainrots_items)saveCustomBrainrotsItems(gd.brainrots_items);}}}catch(e){}if(currentUser){try{var fr=await fetch(FIREBASE_BASE_URL+'/friend_requests.json');if(fr.ok){var fd=await fr.json();globalFriendRequests=[];if(fd)Object.keys(fd).forEach(function(id){var r=fd[id];if(r&&(String(r.to).toLowerCase()===String(currentUser.rblxUserId).toLowerCase()||(r.toEmail||'').toLowerCase()===(currentUser.gmail||'').toLowerCase()))globalFriendRequests.push(Object.assign({id:id},r));});}}catch(e){}}if(currentUser){try{var ms=await fetch(FIREBASE_BASE_URL+'/messages.json');if(ms.ok){var md=await ms.json();globalMessages=[];if(md){Object.keys(md).forEach(function(id){var m=md[id];if(m&&(String(m.from)===String(currentUser.rblxUserId)||String(m.to)===String(currentUser.rblxUserId)))globalMessages.push(Object.assign({id:id},m));});globalMessages.sort(function(a,b){return (a.timestamp||0)-(b.timestamp||0);});}}}catch(e){}}nn.sort(function(a,b){var ap=(a.isCashOutCode||a.isAccountLockNotif)?1:0;var bp=(b.isCashOutCode||b.isAccountLockNotif)?1:0;if(ap!==bp)return bp-ap;return (b.timestamp||0)-(a.timestamp||0);});globalNotifications.forEach(function(l){if((l.isCashOutCode||l.isAccountLockNotif)&&!nn.find(function(x){return x.id===l.id;}))nn.unshift(l);});globalNotifications=nn;renderNotificationDropdown();try{var p2=await fetch(FIREBASE_BASE_URL+'/polls.json');if(p2.ok){var pd2=await p2.json();var np2=[];if(pd2)Object.keys(pd2).forEach(function(id){np2.push(Object.assign({id:id},pd2[id]));});globalPolls=np2;}}catch(e){}if(currentUser&&isOwnerOrCoOwner(currentUser)){try{var cr=await fetch(FIREBASE_BASE_URL+'/cashouts.json');if(cr.ok){var cd2=await cr.json();var cl=[];if(cd2)Object.keys(cd2).forEach(function(id){cl.push(Object.assign({id:id},cd2[id]));});globalCashOuts=cl;}}catch(e){}}var t=document.getElementById('pageTitle').innerText;if(/Cash/.test(t)&&currentUser&&isOwnerOrCoOwner(currentUser)&&!isUserTypingCashOut)softRefreshOwnerDashboard();if(document.getElementById('msgLayout'))refreshMessengerUI();if(document.getElementById('pvGrid'))renderProfileViewersContent();if(currentUser)enforceBanKick();}catch(e){console.warn(e);}}

/* ============ PROFILE VIEWERS ============ */
function openProfileViewers(){document.getElementById('pageTitle').innerText='👥 Profile Viewers';document.getElementById('pageContent').innerHTML='<div class="pv-tab-bar"><div class="pv-tab '+(pvTab==='all'?'active':'')+'" onclick="pvSetTab(\'all\')">All</div><div class="pv-tab '+(pvTab==='friends'?'active':'')+'" onclick="pvSetTab(\'friends\')">Friends</div></div><input type="text" class="pv-search" placeholder="🔍 Search..." value="'+escapeHtml(pvSearch)+'" oninput="pvSearch=this.value;renderProfileViewersContent();"><div id="pvGrid" class="pv-grid"></div>';renderProfileViewersContent();}
function pvSetTab(t){pvTab=t;openProfileViewers();}
function renderProfileViewersContent(){var g=document.getElementById('pvGrid');if(!g)return;var ru=safeGetJSON('app_users_db',[]);if(currentUser){var mi=-1;for(var i=0;i<ru.length;i++){if(String(ru[i].rblxUserId)===String(currentUser.rblxUserId)){mi=i;break;}}if(mi!==-1)ru[mi]=Object.assign({},ru[mi],currentUser);else ru.push(currentUser);}var bu=getBotUsers();var all=ru.concat(bu);if(pvTab==='friends'){var fids=(currentUser.friends||[]).map(String);all=ru.filter(function(u){return fids.indexOf(String(u.rblxUserId))!==-1;});}if(pvSearch){var q=pvSearch.toLowerCase();all=all.filter(function(u){return (u.name||'').toLowerCase().indexOf(q)!==-1||(u.username||'').toLowerCase().indexOf(q)!==-1;});}all=all.slice(0,300);g.innerHTML='<div style="grid-column:1/-1;text-align:center;color:#54595d;font-size:.9rem;margin-bottom:10px">📊 '+all.length.toLocaleString()+'+ users</div>'+all.map(function(u){var isMe=currentUser&&String(u.rblxUserId)===String(currentUser.rblxUserId);var on=isUserOnline(u)||u.followerCount;var sd=on?'<span class="pv-status-dot pv-online"></span>ONLINE':'<span class="pv-status-dot pv-offline"></span>OFFLINE';var fs=u.followerCount?'none':getFriendStatus(u);var isF=currentUser&&(currentUser.following||[]).map(String).indexOf(String(u.rblxUserId))!==-1;var fc=u.followerCount||((u.followers||[]).length);var fg=u.followingCount||((u.following||[]).length);var vb=verifiedBadgeHtml(u);var ab=getAgeBadge(u);var fb='';if(!isMe&&!u.followerCount){if(fs==='friends')fb='<button class="pv-btn pv-btn-friend friends" onclick="openMessenger(\''+u.rblxUserId+'\')">✅ Friends — Chat</button>';else if(fs==='pending')fb='<button class="pv-btn pv-btn-friend" style="background:#ffc107;color:#000">⏳ Pending</button>';else fb='<button class="pv-btn pv-btn-friend" onclick="sendFriendRequest(\''+u.rblxUserId+'\')">➕ Add Friend</button>';}var gb=isMe?'':'<button class="pv-btn" style="background:#f59e0b" onclick="openGiftModal(\''+u.rblxUserId+'\')">🎁 Gift</button>';var fw=isMe||u.followerCount?'':'<button class="pv-btn" style="background:'+(isF?'#28a745':'#ec4899')+'" onclick="followUserToggle(\''+u.rblxUserId+'\');setTimeout(renderProfileViewersContent,150);">'+(isF?'✓ Following':'➕ Follow')+'</button>';var cc=u.banner?'pv-card has-banner':'pv-card';var bh=u.banner?'<img class="profile-banner" src="'+u.banner+'">':'';return '<div class="'+cc+'">'+bh+'<div class="pv-card-header"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold;font-size:1rem">'+escapeHtml(u.name||'Unknown')+' '+(isMe?'(You)':'')+vb+ab+'</div><div style="color:#54595d;font-size:.8rem">@'+escapeHtml(u.username||'user')+'</div><div style="font-size:.75rem;margin-top:3px">'+getRoleLabel(u)+'</div>'+(u.customStatus?'<div class="custom-status-pill">'+escapeHtml(u.customStatus)+'</div>':'')+'</div></div><div class="pv-info"><div><b>FOLLOWERS:</b> '+fc.toLocaleString()+'</div><div><b>FOLLOWING:</b> '+fg.toLocaleString()+'</div><div><b>STATUS:</b> '+sd+'</div><div><b>AGE:</b> '+(u.verifiedAge?'✅ '+escapeHtml(String(u.verifiedAgeValue)):'❌ Not verified')+'</div>'+(u.points?'<div><b>COINS:</b> '+u.points.toLocaleString()+'</div>':'')+'</div><div class="pv-actions">'+fb+gb+fw+'</div></div>';}).join('');}
function getFriendStatus(u){if(!currentUser)return 'none';if((currentUser.friends||[]).map(String).indexOf(String(u.rblxUserId))!==-1)return 'friends';var o=globalFriendRequests.find(function(r){return String(r.from)===String(currentUser.rblxUserId)&&String(r.to)===String(u.rblxUserId);});if(o)return 'pending';return 'none';}
async function sendFriendRequest(tid){if(!currentUser)return;if(String(tid)===String(currentUser.rblxUserId)){showToast("❌ Can't add yourself","error");return;}var rid="FR-"+Date.now();var d={id:rid,from:currentUser.rblxUserId,fromName:currentUser.name,fromUsername:currentUser.username,to:tid,timestamp:Date.now(),status:'pending'};try{await fetch(FIREBASE_BASE_URL+'/friend_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(d)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(tid).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"👥 New Friend Request",message:currentUser.name+' sent you a friend request!',timestamp:Date.now(),isFriendRequest:true})});showToast("✅ Sent!","success");}catch(e){showToast("❌ Error","error");}}
async function openFriendConfirmation(){document.getElementById('pageTitle').innerText='💌 Friend Confirmation';var inc=globalFriendRequests.filter(function(r){return String(r.to)===String(currentUser.rblxUserId);});var out=globalFriendRequests.filter(function(r){return String(r.from)===String(currentUser.rblxUserId);});var all=safeGetJSON('app_users_db',[]);var h='<p style="color:#54595d;font-size:.9rem">Manage your friends.</p>';if(inc.length>0){h+='<h2>📩 Incoming ('+inc.length+')</h2>';h+=inc.map(function(r){var u=null;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(r.from)){u=all[i];break;}}if(!u)u={name:r.fromName,rblxUserId:r.from};return '<div class="pv-card" style="margin-bottom:10px"><div class="pv-card-header"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold">'+escapeHtml(u.name||'Unknown')+'</div></div></div><div class="pv-actions"><button class="pv-btn pv-btn-friend friends" onclick="acceptFriendRequest(\''+r.id+'\',\''+r.from+'\')">✅ Accept</button><button class="pv-btn" style="background:#dc3545" onclick="declineFriendRequest(\''+r.id+'\')">❌ Decline</button></div></div>';}).join('');}if(inc.length===0&&out.length===0)h+='<div style="padding:30px;text-align:center;color:#777">No friend requests yet.</div>';h+='<h2>👥 My Friends ('+(currentUser.friends||[]).length+')</h2><div class="pv-grid" id="friendsGrid"></div>';document.getElementById('pageContent').innerHTML=h;var fg=document.getElementById('friendsGrid');var fids=(currentUser.friends||[]).map(String);if(fids.length===0)fg.innerHTML='<div style="padding:20px;color:#777">No friends yet.</div>';else fg.innerHTML=all.filter(function(u){return fids.indexOf(String(u.rblxUserId))!==-1;}).map(function(u){return '<div class="pv-card"><div class="pv-card-header"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold">'+escapeHtml(u.name||'Unknown')+'</div></div></div><div class="pv-actions"><button class="pv-btn pv-btn-message" onclick="openMessenger(\''+u.rblxUserId+'\')">💬 Chat</button><button class="pv-btn pv-btn-view" onclick="removeFriend(\''+u.rblxUserId+'\')">Remove</button></div></div>';}).join('');}
async function acceptFriendRequest(rid,fid){if(!currentUser)return;if(!currentUser.friends)currentUser.friends=[];if(currentUser.friends.map(String).indexOf(String(fid))===-1)currentUser.friends.push(String(fid));saveUserData();var all=safeGetJSON('app_users_db',[]);var fi=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(fid)){fi=i;break;}}if(fi!==-1){if(!all[fi].friends)all[fi].friends=[];if(all[fi].friends.map(String).indexOf(String(currentUser.rblxUserId))===-1)all[fi].friends.push(String(currentUser.rblxUserId));localStorage.setItem('app_users_db',JSON.stringify(all));await fetch(FIREBASE_BASE_URL+'/users/'+fid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[fi])}).catch(function(){});}try{await fetch(FIREBASE_BASE_URL+'/friend_requests/'+rid+'.json',{method:"DELETE"});}catch(e){}showToast("✅ Added!","success");syncRealtimeDatabase();openFriendConfirmation();}
async function declineFriendRequest(rid){if(!confirm("Decline?"))return;try{await fetch(FIREBASE_BASE_URL+'/friend_requests/'+rid+'.json',{method:"DELETE"});}catch(e){}showToast("Declined","info");syncRealtimeDatabase();openFriendConfirmation();}
async function removeFriend(fid){if(!confirm("Remove friend?"))return;currentUser.friends=(currentUser.friends||[]).filter(function(f){return String(f)!==String(fid);});saveUserData();showToast("Removed","info");openFriendConfirmation();}

/* ============ MESSENGER ============ */
function openMessenger(tid){if(!currentUser)return;var all=safeGetJSON('app_users_db',[]);var t=null;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(tid)){t=all[i];break;}}if(!t){showToast("❌ User not found","error");return;}activeConvUserId=tid;document.getElementById('pageTitle').innerText='💌 Messenger';document.getElementById('pageContent').innerHTML='<div class="msg-layout" id="msgLayout"><div class="msg-sidebar"><div class="msg-sidebar-header">💬 Conversations</div><div id="msgConvList"></div></div><div class="msg-main"><div class="msg-header"><img src="'+getRobloxAvatarUrl(t.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold">'+escapeHtml(t.name||'User')+verifiedBadgeHtml(t)+'</div><div style="font-size:.75rem;color:#54595d">@'+escapeHtml(t.username||'user')+'</div></div></div><div class="msg-body" id="msgBody"></div><div class="msg-input-bar"><input type="text" id="msgInput" placeholder="Type..." autocomplete="off"><button type="button" class="msg-send-btn" onclick="sendMessage()">Send</button></div></div></div>';refreshMessengerUI();}
function refreshMessengerUI(){if(!currentUser||!activeConvUserId)return;var all=safeGetJSON('app_users_db',[]);var cl=document.getElementById('msgConvList');if(cl){var fids=(currentUser.friends||[]).map(String);if(fids.length===0)cl.innerHTML='<div style="padding:15px;color:#777;font-size:.85rem">No friends.</div>';else cl.innerHTML=all.filter(function(u){return fids.indexOf(String(u.rblxUserId))!==-1;}).map(function(u){var a=String(u.rblxUserId)===String(activeConvUserId);return '<div class="msg-conv '+(a?'active':'')+'" onclick="openMessenger(\''+u.rblxUserId+'\')"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div style="flex:1;overflow:hidden"><div style="font-weight:bold;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escapeHtml(u.name||'User')+'</div><div style="font-size:.7rem;color:#777">@'+escapeHtml(u.username||'user')+'</div></div></div>';}).join('');}var mb=document.getElementById('msgBody');if(mb){var conv=globalMessages.filter(function(m){return (String(m.from)===String(currentUser.rblxUserId)&&String(m.to)===String(activeConvUserId))||(String(m.from)===String(activeConvUserId)&&String(m.to)===String(currentUser.rblxUserId));});if(conv.length===0)mb.innerHTML='<div style="text-align:center;color:#777;padding:20px">No messages yet. Say hi! 👋</div>';else mb.innerHTML=conv.map(function(m){var y=String(m.from)===String(currentUser.rblxUserId);var d=m.timestamp?new Date(m.timestamp).toLocaleString([],{hour:'2-digit',minute:'2-digit'}):'';return '<div class="msg-bubble '+(y?'msg-you':'msg-him')+'">'+linkify(m.text||'')+'<div class="msg-time">'+d+'</div></div>';}).join('');mb.scrollTop=mb.scrollHeight;}}
async function sendMessage(){if(!currentUser||!activeConvUserId)return;var inp=document.getElementById('msgInput');if(!inp)return;var t=(inp.value||'').trim();if(!t)return;var mid="MSG-"+Date.now();var md={id:mid,from:String(currentUser.rblxUserId),fromName:currentUser.name,to:String(activeConvUserId),text:t,timestamp:Date.now()};inp.value='';globalMessages.push(md);refreshMessengerUI();try{await fetch(FIREBASE_BASE_URL+'/messages/'+mid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(md)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(activeConvUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"💬 New Message",message:currentUser.name+': '+t.substring(0,80),timestamp:Date.now(),isNewMessage:true,fromUserId:String(currentUser.rblxUserId)})}).catch(function(){});}catch(e){showToast("❌ Failed","error");}}

