h+='<div style="margin-bottom:15px;background:rgba(248,249,250,.95);border:1px solid #a2a9b1;padding:15px;border-radius:6px"><label style="font-weight:bold;display:block;margin-bottom:5px">🖼️ Custom Avatar</label><p style="font-size:.78rem;color:#54595d;margin:4px 0 8px">Upload your own (auto-crop circle).</p><input type="file" accept="image/*" onchange="handleAvatarUpload(this)" style="width:100%;padding:8px;border:1px solid #a2a9b1;border-radius:4px">'+(u.customAvatar?'<button class="btn-danger" style="margin-top:8px;width:100%" onclick="removeCustomAvatar()">↩️ Reset</button>':'')+'</div>';
