h+='<div style="margin-bottom:15px;background:rgba(139,92,246,.1);border:1px solid #c4b5fd;padding:15px;border-radius:6px"><label style="font-weight:bold;display:block;margin-bottom:5px">🪪 Verified Aged</label>'+asb+'</div>';
h+='<div style="margin-bottom:15px;background:rgba(234,243,255,.9);border:1px solid #a7d7f9;padding:12px;border-radius:6px"><label style="font-weight:bold;display:block;margin-bottom:5px">History Privacy 🔒</label><button class="btn-save" onclick="togglePrivacySetting()">'+pt+'</button></div>';
