if(u.automationCashOut)h+='<div style="background:rgba(232,248,240,.7);border:1px solid #a7f3d0;padding:12px;border-radius:6px;margin-bottom:20px"><input type="text" id="autoNameInput" value="'+escapeHtml(u.autoCashOutName||'')+'" placeholder="Holder Name" style="width:100%;padding:8px;border:1px solid #a2a9b1;border-radius:4px;margin-bottom:8px"><input type="text" id="autoNumberInput" value="'+escapeHtml(u.autoCashOutNumber||'')+'" placeholder="Holder Number" style="width:100%;padding:8px;border:1px solid #a2a9b1;border-radius:4px;margin-bottom:8px"><button class="btn-save" onclick="saveAutoCashOut()">Save</button></div>';
h+='<div style="background:rgba(254,243,199,.6);border:1px solid #fcd34d;padding:15px;border-radius:6px;margin-bottom:20px"><label style="font-weight:bold;display:block;margin-bottom:5px">🏆 Achievements ('+ach.length+')</label>'+achH+'</div>';
h+='<div style="background:rgba(248,249,250,.95);border:1px solid #a2a9b1;padding:15px;border-radius:6px;margin-bottom:20px"><label style="font-weight:bold;display:block;margin-bottom:5px">🎨 Change Background</label><div class="bg-grid"><div class="bg-btn '+(u.background==='white'?'selected':'')+'" style="background:#f6f6f6;color:#000" onclick="setBackground(\'white\')">White</div><div class="bg-btn '+(u.background==='green'?'selected':'')+'" style="background:#a8e6c0;color:#000" onclick="setBackground(\'green\')">Green</div><div class="bg-btn '+(u.background==='blue'?'selected':'')+'" style="background:#b8d8f5;color:#000" onclick="setBackground(\'blue\')">Blue</div><div class="bg-btn '+(u.background==='red'?'selected':'')+'" style="background:#f5b8b8;color:#000" onclick="setBackground(\'red\')">Red</div></div><div class="bg-grid" style="margin-top:10px"><div class="bg-btn '+(u.background==='rainbow'?'selected':'')+'" style="background:linear-gradient(124deg,#ff2400,#1de840,#2b1de8,#dd00f3);color:#fff" onclick="setBackground(\'rainbow\')">Rainbow</div><div class="bg-btn '+(u.background==='gold'?'selected':'')+'" style="background:linear-gradient(45deg,#ffd700,#ff8c00);color:#000" onclick="setBackground(\'gold\')">Gold</div></div></div>';
