function gstSetTab(t){gstTab=t;document.querySelectorAll('.gst-tab').forEach(function(b){var on=b.dataset.gst===t;b.classList.toggle('active',on);});runGlobalSearch((document.getElementById('globalSearchInputOverlay')||{}).value||'');}
function runGlobalSearch(q){q=(q||'').trim().toLowerCase();var r=document.getElementById('globalSearchResults');if(!r)return;if(!q){r.innerHTML='<p style="text-align:center;color:#777;padding:30px">🔍 Type to search users, products, posts, achievements...</p>';return;}var h='';if(gstTab==='all'||gstTab==='users'){var au=safeGetJSON('app_users_db',[]);var mu=au.filter(function(u){return (u.name||'').toLowerCase().indexOf(q)!==-1||(u.username||'').toLowerCase().indexOf(q)!==-1||String(u.rblxUserId||'').indexOf(q)!==-1;}).slice(0,20);if(mu.length>0){h+='<h4 style="margin:0 0 10px;color:#3366cc">👥 Users ('+mu.length+')</h4>';h+=mu.map(function(u){return '<div class="gso-item" onclick="closeGlobalSearch();openMessenger(\''+u.rblxUserId+'\')"><img class="gso-avatar" src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold;font-size:.9rem">'+escapeHtml(u.name||'Unknown')+verifiedBadgeHtml(u)+'</div><div style="font-size:.75rem;color:#54595d">@'+escapeHtml(u.username||'user')+'</div></div></div>';}).join('');}}
if(gstTab==='all'||gstTab==='products'){var pr=getAllShopProducts();var mp=pr.filter(function(p){return (p.name||'').toLowerCase().indexOf(q)!==-1||(p.category||'').toLowerCase().indexOf(q)!==-1;}).slice(0,20);if(mp.length>0){h+='<h4 style="margin:16px 0 10px;color:#8b5cf6">🛍️ Products ('+mp.length+')</h4>';h+=mp.map(function(p){return '<div class="gso-item"><img class="gso-thumb" src="'+escapeHtml(p.image||'')+'" onerror="this.style.background=\'#eaecf0\'"><div><div style="font-weight:bold">'+escapeHtml(p.name)+'</div><div style="font-size:.72rem;color:#8b5cf6">'+escapeHtml(p.category||'')+'</div><div style="font-size:.85rem;color:#28a745;font-weight:bold;margin-top:4px">₱'+(p.priceMoney||0).toLocaleString()+'</div></div></div>';}).join('');}}
if(gstTab==='all'||gstTab==='posts'){var sh=getAllImgShots();var ms=sh.filter(function(v){return (v.title||'').toLowerCase().indexOf(q)!==-1||(v.description||'').toLowerCase().indexOf(q)!==-1||(v.code||'').toLowerCase().indexOf(q)!==-1;}).slice(0,20);if(ms.length>0){h+='<h4 style="margin:16px 0 10px;color:#ec4899">🖼️ Posts ('+ms.length+')</h4>';h+=ms.map(function(v){return '<div class="gso-item" onclick="closeGlobalSearch();openVideoShares()"><img class="gso-thumb" src="'+escapeHtml(v.media||'')+'" onerror="this.style.background=\'#eaecf0\'"><div><div style="font-weight:bold">'+escapeHtml(v.title||'Untitled')+'</div><div style="font-size:.72rem;color:#54595d">@'+escapeHtml(v.uploaderUsername||'')+'</div><div style="font-size:.7rem;color:#ec4899;font-family:monospace;margin-top:4px">'+escapeHtml(v.code||'')+'</div></div></div>';}).join('');}}
if(gstTab==='all'||gstTab==='achievements'){var ma=ACHIEVEMENTS.filter(function(a){return (a.name||'').toLowerCase().indexOf(q)!==-1||(a.desc||'').toLowerCase().indexOf(q)!==-1;});if(ma.length>0){h+='<h4 style="margin:16px 0 10px;color:#f59e0b">🏆 Achievements ('+ma.length+')</h4>';h+=ma.map(function(a){return '<div class="gso-item"><div style="font-size:2rem">'+a.icon+'</div><div><div style="font-weight:bold">'+escapeHtml(a.name)+'</div><div style="font-size:.75rem;color:#54595d">'+escapeHtml(a.desc)+'</div></div></div>';}).join('');}}
if(!h)h='<p style="text-align:center;color:#777;padding:30px">No results for "<b>'+escapeHtml(q)+'</b>"</p>';r.innerHTML=h;}

