async function addOwnerOrCoOwner(t){if(!currentUser||!isOwnerAccount(currentUser))return;var tg=document.getElementById('ownAddTarget').value.trim();var usr=findUserByIdentifier(tg);if(!usr){showToast("❌ Not found","error");return;}if(!confirm('Promote '+(usr.name||usr.username)+' to '+t+'?'))return;var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr);if(t==='Owner'){upd.isOwner=true;upd.isAdmin=true;upd.role='Owner';}else{upd.isCoOwner=true;upd.isAdmin=true;upd.role='Co-Owner';}if(ix!==-1)all[ix]=upd;else all.push(upd);localStorage.setItem('app_users_db',JSON.stringify(all));try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('👑 Done','success');renderStaffCommandsPage();}catch(e){showToast("❌ Failed","error");}}
async function removeOwnerOrCoOwner(t){if(!currentUser||!isOwnerAccount(currentUser))return;var tg=document.getElementById('ownAddTarget').value.trim();var usr=findUserByIdentifier(tg);if(!usr){showToast("❌ Not found","error");return;}if(String(usr.rblxUserId)===String(currentUser.rblxUserId)){showToast("❌ Can't remove yourself","error");return;}if(!confirm('Remove '+t+'?'))return;var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr);if(t==='Owner'){upd.isOwner=false;upd.role=upd.isCoOwner?'Co-Owner':(upd.isAdmin?'Admin':'Member');}else{upd.isCoOwner=false;upd.role=upd.isAdmin?'Admin':'Member';}if(ix!==-1)all[ix]=upd;localStorage.setItem('app_users_db',JSON.stringify(all));try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('✅ Removed','success');renderStaffCommandsPage();}catch(e){showToast("❌ Failed","error");}}
async function createAnnouncement(p){if(!currentUser||!isUserAdmin(currentUser))return;var t=document.getElementById(p+'AnnTitle').value.trim();var m=document.getElementById(p+'AnnMessage').value.trim();if(!t||!m){showToast("❌ Fill all","error");return;}var nid="ANN-"+Date.now();var nd={id:nid,title:'📢 '+t,message:m,timestamp:Date.now(),isAnnouncement:true,sender:currentUser.name||currentUser.username,senderRole:getSenderRoleLabel(currentUser)};try{await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(nd)});showToast("📢 Deployed!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function updateUserRole(ti,role,action){if(!currentUser)return;if(role==='Admin'&&!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}if(role==='Moderator'&&!isOwnerOrCoOwner(currentUser)&&!isUserAdmin(currentUser)){showToast("❌ Staff only","error");return;}var el=document.getElementById(ti);var tt=el?el.value.trim().toLowerCase():'';if(!tt){showToast("❌ Enter target","error");return;}var au=safeGetJSON('app_users_db',[]);var fi=-1;for(var i=0;i<au.length;i++){if(String(au[i].rblxUserId||'').toLowerCase()===tt||(au[i].gmail||'').toLowerCase()===tt||(au[i].username||'').toLowerCase()===tt){fi=i;break;}}if(fi===-1){showToast("❌ Not found","error");return;}var tu=au[fi];if(isOwnerAccount(tu)){showToast('👑 Owner','error');return;}if(action==='give'){if(role==='Admin'){tu.isAdmin=true;tu.role='Admin';}else{tu.isMod=true;tu.role=tu.isAdmin?'Admin':'Moderator';}}else{if(role==='Admin'){tu.isAdmin=false;tu.role=tu.isMod?'Moderator':'Member';}else{tu.isMod=false;tu.role=tu.isAdmin?'Admin':'Member';}}au[fi]=tu;localStorage.setItem('app_users_db',JSON.stringify(au));try{await fetch(FIREBASE_BASE_URL+'/users/'+tu.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(tu)});showToast('✅ Done','success');}catch(e){showToast("❌ Error","error");}renderStaffCommandsPage();}
async function createPollWithImage(p){var t=document.getElementById(p+'PollTitle').value.trim();var d=document.getElementById(p+'PollDesc').value.trim();var os=document.getElementById(p+'PollOptions').value.trim();var fi=document.getElementById(p+'PollImage');if(!t||!os){showToast("❌ Fill all","error");return;}var opt=os.split(',').map(function(o){return {name:o.trim(),votes:0};}).filter(function(o){return o.name!=="";});if(opt.length<2){showToast("❌ 2+ options","error");return;}var sp=async function(img){var pid='poll_'+Date.now();var po={id:pid,title:t,description:d,options:opt,timestamp:Date.now()};if(img)po.image=img;try{await fetch(FIREBASE_BASE_URL+'/polls/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(po)});showToast("✅ Created!","success");syncRealtimeDatabase();openStaffCommands();}catch(e){showToast("❌ Error","error");}};if(fi.files.length>0){var f=fi.files[0];if(f.size>2*1024*1024){showToast("❌ Max 2MB","error");return;}var r=new FileReader();r.onload=function(e){sp(e.target.result);};r.readAsDataURL(f);}else sp(null);}
async function sendGlobalOwnerNotification(){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;var t=document.getElementById('ownNotifTitle').value.trim();var m=document.getElementById('ownNotifMsg').value.trim();var a=document.getElementById('ownNotifAudience').value;var ti=document.getElementById('ownNotifTarget').value.trim().toLowerCase();if(!t||!m){showToast("❌ Fill all","error");return;}var nid="NOTIF-"+Date.now();var nd={id:nid,title:t,message:m,sender:currentUser.name||currentUser.username,senderRole:getSenderRoleLabel(currentUser),timestamp:Date.now()};var ep=FIREBASE_BASE_URL+'/notifications/'+nid+'.json';if(a==='specific')ep=FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(ti)+'/'+nid+'.json';try{await fetch(ep,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(nd)});showToast("📢 Sent!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function uploadSneakPeek(){if(!currentUser||!isStaff(currentUser))return;var t=document.getElementById('ownSneakTitle').value.trim();var d=document.getElementById('ownSneakDesc').value.trim();var fi=document.getElementById('ownSneakImage');if(!t||!d||fi.files.length===0){showToast("❌ Fill all","error");return;}var f=fi.files[0];if(f.size>2*1024*1024){showToast("❌ Max 2MB","error");return;}var r=new FileReader();r.onload=async function(e){var sid="SNEAK-"+Date.now();try{await fetch(FIREBASE_BASE_URL+'/sneak_peeks/'+sid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:sid,title:t,description:d,image:e.target.result,timestamp:Date.now(),uploader:currentUser.username||currentUser.name})});showToast("✅ Uploaded!","success");syncRealtimeDatabase();}catch(err){showToast("❌ Error","error");}};r.readAsDataURL(f);}
async function grantCoinsToUser(p){if(!currentUser||!isUserAdmin(currentUser)){showToast("❌ Admin+ only","error");return;}var ti=(document.getElementById(p+'GrantTarget').value||'').trim().toLowerCase();var ca=document.getElementById(p+'GrantAmount').value;if(!ti){showToast("❌ Enter target","error");return;}var cta=parseInt(ca,10);if(isNaN(cta)||cta<=0){showToast("❌ Valid amount","error");return;}var au=safeGetJSON('app_users_db',[]);var fi=-1;for(var i=0;i<au.length;i++){if(String(au[i].rblxUserId||'').toLowerCase()===ti||(au[i].gmail||'').toLowerCase()===ti||(au[i].username||'').toLowerCase()===ti){fi=i;break;}}if(fi===-1){showToast("❌ Not found","error");return;}var tu=au[fi];tu.points=(tu.points||0)+cta;tu.lastSeen=new Date().toISOString();au[fi]=tu;localStorage.setItem('app_users_db',JSON.stringify(au));if(String(tu.rblxUserId)===String(currentUser.rblxUserId)){currentUser.points=tu.points;localStorage.setItem('app_current_user',JSON.stringify(currentUser));updateUserStatusHeader();}try{await fetch(FIREBASE_BASE_URL+'/users/'+tu.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(tu)});var nid="CG-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(tu.rblxUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🪙 Coins Received!",message:'You received '+cta.toLocaleString()+' Coins!',timestamp:Date.now(),isCoinGift:true})});showToast('⚡ Granted '+cta.toLocaleString(),'success');syncRealtimeDatabase();}catch(e){showToast("❌ Error","error");}}
async function createXdrgProduct(p){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}var nm=document.getElementById(p+'ProdName').value.trim();var pm=parseFloat(document.getElementById(p+'ProdPriceMoney').value)||0;var pc=parseInt(document.getElementById(p+'ProdPriceCoins').value,10)||0;var cat=document.getElementById(p+'ProdCategory').value;var desc=document.getElementById(p+'ProdDesc').value.trim();var fi=document.getElementById(p+'ProdImage');var fmi=document.getElementById(p+'ProdImages');if(!nm){showToast("❌ Enter name","error");return;}if(fi.files.length===0){showToast("❌ Add main image","error");return;}var mf=fi.files[0];if(mf.size>3*1024*1024){showToast("❌ Max 3MB","error");return;}var r=new FileReader();r.onload=async function(e){var pid="PROD-"+Date.now();var extra=[];var extras=[];if(fmi&&fmi.files){for(var k=0;k<fmi.files.length&&k<4;k++){var ef=fmi.files[k];if(ef.size>3*1024*1024)continue;extras.push(ef);}}var readExtra=function(idx){return new Promise(function(res){if(idx>=extras.length){res();return;}var rr=new FileReader();rr.onload=function(ee){extra.push(ee.target.result);readExtra(idx+1).then(res);};rr.readAsDataURL(extras[idx]);});};await readExtra(0);var prod={id:pid,name:nm,priceMoney:pm,priceCoins:pc,category:cat,description:desc,image:e.target.result,images:[e.target.result].concat(extra),createdBy:currentUser.username||currentUser.name,timestamp:Date.now()};var all=getAllShopProducts();all.push(prod);saveAllShopProducts(all);try{await fetch(FIREBASE_BASE_URL+'/xdrg_shop/products/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(prod)});showToast("✅ Created!","success");renderStaffCommandsPage();}catch(err){showToast("❌ Error","error");}};r.readAsDataURL(mf);}
async function activateLimitedCashOut(p){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}var m=parseInt(document.getElementById(p+'LcoMoney').value,10);var d=parseInt(document.getElementById(p+'LcoDuration').value,10);var u=document.getElementById(p+'LcoUnit').value;var cc=parseInt(document.getElementById(p+'LcoCostCoins').value,10);if(isNaN(m)||m<1||isNaN(d)||d<1||isNaN(cc)||cc<1){showToast("❌ Valid inputs","error");return;}var mlt={minutes:60000,hours:3600000,days:86400000,weeks:604800000,months:2592000000,years:31536000000};var ea=Date.now()+d*mlt[u];var obj={money:m,costCoins:cc,expiresAt:ea,activatedBy:currentUser.username||currentUser.name,activatedAt:Date.now()};try{await fetch(FIREBASE_BASE_URL+'/limited_cashout.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(obj)});var nid="LCO-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"Limited Cash Out 🤑🎉!!!",message:'cash out now the limited Cash out until Limited Cash out is banish!🎉📌 ₱'+m,timestamp:Date.now(),isLimitedCashOut:true,money:m})});globalLimitedCashOut=obj;showToast("🚀 ACTIVATED!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function deactivateLimitedCashOut(){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;if(!confirm("Cancel?"))return;try{await fetch(FIREBASE_BASE_URL+'/limited_cashout.json',{method:"DELETE"});globalLimitedCashOut=null;showToast("✅ Cancelled","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}

/* ============ GAME SETUP ============ */
function openGameSetup(t){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only!","error");return;}currentSetupType=t;editingSetupIndex=-1;if(t==='crystal'){currentSetupItems=getCustomCrystalItems().slice();document.getElementById('gameSetupTitle').innerText='💎 Crystal Setup';}else{currentSetupItems=getCustomBrainrotsItems().slice();document.getElementById('gameSetupTitle').innerText='🚂 Brainrots Setup';}renderGameSetup();var o=document.getElementById('gameSetupOverlay');if(o)o.classList.add('active');document.body.style.overflow='hidden';}
function closeGameSetup(){var o=document.getElementById('gameSetupOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';}
function renderGameSetup(){var c=document.getElementById('gameSetupContent');if(!c)return;var isC=currentSetupType==='crystal';var ttl=isC?'💎 Crystal':'🚂 Brainrots';var h='<div class="age-form-box"><h3>'+ttl+' — Item Setup</h3><p style="font-size:.88rem;color:#c4b5fd">Fill details, click Next to add. Publish when done.</p>';if(isC){h+='<div class="setup-field"><div><label>Item Name</label><input type="text" id="gsName"></div><div><label>Cost (₱)</label><input type="number" id="gsCost" min="0"></div></div><div class="setup-field"><div><label>Health</label><input type="number" id="gsHealth" min="0"></div><div><label>Duration</label><input type="text" id="gsDuration"></div></div><div class="setup-field"><div><label>Rarity</label><select id="gsRarity"><option>Common</option><option>Rare</option><option>Legendary</option><option>Mythic</option><option>Godly</option><option>Limited</option></select></div><div></div></div>';}else{h+='<div class="setup-field"><div><label>Item Name</label><input type="text" id="gsName"></div><div><label>Cost (₱)</label><input type="number" id="gsCost" min="0"></div></div><div class="setup-field"><div><label>Per Second</label><input type="text" id="gsPerSecond"></div><div><label>Rarity</label><select id="gsRarity"><option>Common</option><option>Rare</option><option>Legendary</option><option>Mythic</option><option>Godly</option><option>Limited</option></select></div></div><div class="setup-field"><div><label>Area</label><input type="text" id="gsArea"></div><div></div></div>';}
h+='<div class="setup-actions"><button style="background:#005a9c;color:#fff" onclick="nextGameSetupItem()">➡️ Next</button><button style="background:#28a745;color:#fff" onclick="publishGameSetup()">📤 Publish</button></div></div>';h+='<div style="margin-top:22px"><h3 style="color:#a78bfa">📋 Items ('+currentSetupItems.length+')</h3>';if(currentSetupItems.length===0)h+='<p style="color:#94a3b8;font-size:.85rem">No items yet.</p>';else currentSetupItems.forEach(function(it,i){var ex=isC?('Cost: '+it.cost+' HP: '+it.health+' Dur: '+it.duration+' R: '+it.rarity):('Cost: '+it.cost+' /s: '+it.perSecond+' R: '+it.rarity+' A: '+it.area);h+='<div class="setup-item-row"><div><b>#'+(i+1)+' '+escapeHtml(it.name)+'</b><br><small style="opacity:.75">'+escapeHtml(ex)+'</small></div><div class="sir-actions"><button style="background:#dc3545;color:#fff" onclick="removeGameSetupItem('+i+')">🗑️</button></div></div>';});h+='</div>';if(currentSetupItems.length>0)h+='<div class="setup-actions"><button style="background:#28a745;color:#fff;font-weight:900" onclick="publishGameSetup()">📤 PUBLISH ALL ('+currentSetupItems.length+')</button></div>';h+='<div class="setup-actions"><button style="background:#6c757d;color:#fff" onclick="closeGameSetup()">✕ Close</button></div>';c.innerHTML=h;}
function nextGameSetupItem(){var isC=currentSetupType==='crystal';var nm=(document.getElementById('gsName').value||'').trim();var co=parseFloat(document.getElementById('gsCost').value)||0;var ra=document.getElementById('gsRarity').value;if(!nm){showToast("❌ Enter name","error");return;}var it;if(isC){it={name:nm,cost:co,health:parseFloat(document.getElementById('gsHealth').value)||0,duration:(document.getElementById('gsDuration').value||'').trim(),rarity:ra};}else{it={name:nm,cost:co,perSecond:(document.getElementById('gsPerSecond').value||'').trim(),rarity:ra,area:(document.getElementById('gsArea').value||'').trim()};}if(editingSetupIndex>=0){currentSetupItems[editingSetupIndex]=it;editingSetupIndex=-1;}else currentSetupItems.push(it);['gsName','gsCost','gsHealth','gsDuration','gsPerSecond','gsArea'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});showToast("✅ Item added","success");renderGameSetup();}
function removeGameSetupItem(i){if(i<0||i>=currentSetupItems.length)return;if(!confirm("Remove?"))return;currentSetupItems.splice(i,1);if(editingSetupIndex===i)editingSetupIndex=-1;renderGameSetup();}
async function publishGameSetup(){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;if(currentSetupItems.length===0){showToast("❌ No items","error");return;}var isC=currentSetupType==='crystal';if(isC)saveCustomCrystalItems(currentSetupItems);else saveCustomBrainrotsItems(currentSetupItems);var k=isC?'crystal_items':'brainrots_items';try{await fetch(FIREBASE_BASE_URL+'/xdrg_game_setup/'+k+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(currentSetupItems)});var nid="GS-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🎮 Game Setup Updated!",message:(isC?'Crystal':'Brainrots')+' updated with '+currentSetupItems.length+' items.',timestamp:Date.now()})});}catch(e){}showToast("✅ Published!","success");syncRealtimeDatabase();closeGameSetup();}

/* ============ AUTOMATION TOGGLE (top bar) ============ */
function _applyUserPrefs(){if(!currentUser)return;if(currentUser.darkMode)document.body.classList.add('dark');_sfxUpdateBtn();}

/* ============ WINDOW.ONLOAD ============ */
window.onload=function(){
  try{
    if("Notification" in window&&Notification.permission!=="granted"&&Notification.permission!=="denied")Notification.requestPermission();
    var up=new URLSearchParams(window.location.search);
    var vsCode=up.get('xdrgimg')||up.get('xdrgvideo');
    var ref=up.get('ref');
    if(ref){localStorage.setItem('activeReferrer',ref);var ab=document.getElementById('refDetectAlert');if(ab){ab.innerText='🔗 Referral Link Detected!';ab.style.display='block';}}
    var sl=localStorage.getItem('app_language')||'en';
    currentLanguage=sl;getBotUsers();
    var su=safeGetJSON('app_current_user',null);
    if(su){
      currentUser=su;
      var defaults={isHistoryPublic:false,wrongPasswordAttempts:0,accountLockedUntil:0,friends:[],following:[],followers:[],isVerified:false,verifiedExpiry:0,cashBalance:0,extraSpins:0,verifiedAge:false,verifiedAgeValue:null,ageAppealCount:0,lastAgeAppealTime:0,pendingAgeAppeal:null,automationCashOut:false,autoCashOutName:'',autoCashOutNumber:'',changeNameCount:0,changeUserIdCount:0,shopCart:[],inventory:[],darkMode:false,soundEnabled:true,customAvatar:'',banner:'',customStatus:''};
      Object.keys(defaults).forEach(function(k){if(currentUser[k]===undefined)currentUser[k]=defaults[k];});
      if(isOwnerAccount(currentUser)){currentUser.isOwner=true;currentUser.isAdmin=true;}
      updateUserStatusHeader();logDeviceConnection(currentUser);showWiki();applyBackground(currentUser.background||'white');
      _applyUserPrefs();
      checkDailyReward();enforceBanKick();
    }
    setLanguage(sl);
    document.addEventListener('click',function(){var d=document.getElementById('notifDropdown');if(d)d.classList.remove('active');});
    var gsi=document.getElementById('globalSearchInput');
    if(gsi)gsi.addEventListener('input',function(){clearTimeout(gstDebounce);var v=this.value;gstDebounce=setTimeout(function(){runGlobalSearch(v);var ov=document.getElementById('globalSearchInputOverlay');if(ov)ov.value=v;if(v.trim()&&(!document.getElementById('globalSearchOverlay')||document.getElementById('globalSearchOverlay').style.display!=='flex')){var o=document.getElementById('globalSearchOverlay');if(o){o.style.display='flex';o.classList.add('active');document.body.style.overflow='hidden';}}},200);});
    var gsio=document.getElementById('globalSearchInputOverlay');
    if(gsio)gsio.addEventListener('input',function(){clearTimeout(gstDebounce);var v=this.value;gstDebounce=setTimeout(function(){runGlobalSearch(v);if(gsi)gsi.value=v;},200);});
    var gso=document.getElementById('globalSearchOverlay');
    if(gso)gso.addEventListener('click',function(e){if(e.target===this)closeGlobalSearch();});
    document.addEventListener('keydown',function(e){
      if((e.ctrlKey||e.metaKey)&&(e.key==='k'||e.key==='K')){e.preventDefault();openGlobalSearch();}
      if(e.key==='Escape'){
        var m=document.getElementById('uploadModal');if(m&&m.classList.contains('active'))closeUploadUI();
        var gs=document.getElementById('globalSearchOverlay');if(gs&&gs.style.display==='flex')closeGlobalSearch();
        var gm=document.getElementById('giftModal');if(gm&&gm.style.display==='flex')closeGiftModal();
        var gal=document.getElementById('galleryModal');if(gal&&gal.style.display==='flex')closeGalleryModal();
      }
    });
    if(syncInterval)clearInterval(syncInterval);
    syncInterval=setInterval(syncRealtimeDatabase,2000);
    syncRealtimeDatabase();
    setTimeout(checkIncomingTrades,2500);
    setInterval(checkIncomingTrades,15000);
    if(vsCode)setTimeout(function(){openVideoShares();},600);
    var gsp=document.getElementById('tradePartnerInput');
    if(gsp)gsp.addEventListener('input',function(){_tradePartnerId=this.value.trim();});
  }catch(err){console.error(err);}
};
